contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // Precondition: caller must not be the original deployer / owner.
        // The owner is msg.sender of the constructor, which is the test deployer.
        // Since we do not have a public owner getter, we instead enforce that
        // the caller does not revert for a known owner-only action.
        // We detect ownership by checking that `OpenToThePublic` does not revert
        // from a candidate sender. Since OpenToThePublic is onlyOwner, only the
        // owner can call it without revert. So we require that caller is NOT
        // the owner by verifying OpenToThePublic reverts from caller.
        require(c.OpenToThePublic{from: address(uint160(caller))}() == false, "pre: owner cannot be caller");
        bool reverted;
        try c.AdjustBetAmounts{from: address(uint160(caller))}(1) { reverted = false; } catch { reverted = true; }
        assert(reverted == true);
    }
    receive() external payable {}
}

