pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 newBetLimit, address attacker) public {
        // 1. Admissible domain: attacker must not be the owner (address(this))
        vm.assume(attacker != address(this));
        // 2. Record current betLimit before the call
        uint256 expected = c.currentBetLimit();
        // 3. Let attacker call AdjustBetAmounts
        vm.prank(attacker);
        c.AdjustBetAmounts(newBetLimit);
        // 4. After the call, betLimit in the reference contract MUST remain unchanged
        assertTrue(c.currentBetLimit() == expected);
    }
}

